create or replace function public.review_cheque(p_cheque uuid,p_decision text,p_note text default '') returns public.cheques language plpgsql security definer set search_path=public as $$ declare c public.cheques; tx uuid; reviewer_role public.bank_role; begin
 select role into reviewer_role from public.profiles where id=auth.uid() and status='active';
 if reviewer_role is null or reviewer_role not in ('clearing_staff','admin') or p_decision is null or p_decision not in ('approve','reject') then raise exception 'Only active clearing staff or administrators may decide cheques'; end if;
 select * into c from public.cheques where id=p_cheque for update;
 if not found or c.status<>'queued' then raise exception 'Cheque is not awaiting review'; end if;
 if c.submitted_by=auth.uid() or public.has_account_access(c.account_id,'view') or public.has_account_access(c.payee_account_id,'view') then raise exception 'An independent reviewer with no interest in either account is required'; end if;
 if extract(isodow from now() at time zone 'UTC')>5 or exists(select 1 from public.bank_holidays where holiday_date=(now() at time zone 'UTC')::date) then raise exception 'Bank is closed today'; end if;
 if (now() at time zone 'UTC')::time>=time '16:30' then raise exception 'Clearing cut-off has passed'; end if;
 if p_decision='approve' then tx:=public.post_ledger_transaction('Cheque settlement '||c.cheque_number,c.account_id,c.payee_account_id,c.amount,'cheque:'||c.id::text); update public.cheques set status='settled',reviewed_by=auth.uid(),reviewed_at=now(),decision_note=p_note,settled_transaction_id=tx where id=p_cheque returning * into c; else update public.cheques set status='rejected',reviewed_by=auth.uid(),reviewed_at=now(),decision_note=p_note where id=p_cheque returning * into c; end if;
 insert into public.staff_decisions(cheque_id,staff_id,decision,note) values(c.id,auth.uid(),p_decision,coalesce(p_note,'')); insert into public.audit_events(actor_id,action,target_type,target_id,metadata) values(auth.uid(),'cheque_'||p_decision,'cheque',c.id::text,jsonb_build_object('note',p_note)); insert into public.notification_outbox(recipient_user_id,event_type,payload) values(c.submitted_by,'cheque_'||p_decision,jsonb_build_object('cheque_id',c.id,'cheque_number',c.cheque_number)); return c; end $$;
